def choose_move(observation):
    # Defensive defaults
    x = observation.get("position", {}).get("x", 0)
    y = observation.get("position", {}).get("y", 0)

    # Try to infer map size if available
    grid_w = observation.get("grid", {}).get("width", None)
    grid_h = observation.get("grid", {}).get("height", None)

    # Helper: clamp move to [-1,0,1]
    def clamp(v):
        if v < -1:
            return -1
        if v > 1:
            return 1
        return v

    # Default to staying
    dx, dy = 0, 0

    # If there are visible resources, bias toward closest resource
    resources = observation.get("resources", [])
    if isinstance(resources, list) and resources:
        # Find nearest resource by Manhattan distance
        best = None
        best_dist = None
        for r in resources:
            rx = r.get("x", None)
            ry = r.get("y", None)
            if rx is None or ry is None:
                continue
            dist = abs(rx - x) + abs(ry - y)
            if best_dist is None or dist < best_dist:
                best_dist = dist
                best = (rx, ry)
        if best is not None:
            rx, ry = best
            dx = clamp(rx - x)
            dy = clamp(ry - y)

    # If no resources or move still (0,0), consider foes or territory
    if dx == 0 and dy == 0:
        foes = observation.get("foes", [])
        if isinstance(foes, list) and foes:
            # Move toward the closest foe to pursue or threaten
            best = None
            best_dist = None
            for f in foes:
                fx = f.get("x", None)
                fy = f.get("y", None)
                if fx is None or fy is None:
                    continue
                dist = abs(fx - x) + abs(fy - y)
                if best_dist is None or dist < best_dist:
                    best_dist = dist
                    best = (fx, fy)
            if best is not None:
                fx, fy = best
                dx = clamp(fx - x)
                dy = clamp(fy - y)

    # If still no move, try to expand territory by moving toward center if grid known
    if dx == 0 and dy == 0:
        if grid_w is not None and grid_h is not None:
            center_x = max(0, grid_w // 2)
            center_y = max(0, grid_h // 2)
            dx = clamp(center_x - x)
            dy = clamp(center_y - y)

    # Final safeguard: ensure within allowed delta
    dx = -1 if dx < -1 else (1 if dx > 1 else dx)
    dy = -1 if dy < -1 else (1 if dy > 1 else dy)

    return [dx, dy]

